 coverage={'version':VERSION,'editions':full['editions'],'fulltext_units':sum(e['units'] for e in full['editions']),'catalog_records':len(records),'historical_inventory_records':len(inventory),'studies':{'total':len(studies),'checked':sum(r.get('verification_status')=='checked' for r in studies)},'lexicon':{'total':len(lexicon),'locally_marked_verified':sum(bool(e.get('verified')) for e in lexicon)},'notes':{'total':len(notes),'explicit_locus':sum(bool(n.get('locus')) for n in notes),'requires_locus_review':sum(not n.get('locus') for n in notes)},'semantic':cat['semantic'],'limitations':['Automated mapping is not independent philological collation.','An explicit note anchor is not a certified manuscript variant.','No DOI or ORCID is invented; ISBN is retained only when present in the source.']}
 write('data/coverage.json',coverage)
 body='<p class="eyebrow">CATÁLOGO RAZONADO</p><h1>La colección</h1><p>Catálogo completo disponible sin JavaScript. Cada ficha distingue texto indexado, OCR histórico y fuente institucional enlazada. Versión '+VERSION+'.</p><p><a href="data/catalog-completo.json" download>Descargar catálogo JSON</a> · <a href="lectura/index.html">Leer las tres ediciones por libro</a> · <a href="data/releases/'+VERSION+'.json">Manifiesto de versión</a></p>'
