    page=unit.get('pdf_pages',{}).get('translation') or unit.get('pdf_pages',{}).get('latin');content+='<article class="context-unit" id="'+unit['locus']+'"><h2>Vitr., De arch. '+reference(unit)+'</h2>'
    if unit.get('scope_note'):content+='<p class="meta">'+esc(unit['scope_note'])+'</p>'
