 source=ROOT/'loci.html';s=source.read_text();start=s.index('<div class="libro"');end=s.index('<footer',start);blocks=[];passages=read('data/structured/recensio-es.json')['passages']
 for book in range(1,11):blocks.append('<div class="libro" data-libro="'+roman(book)+'"><h2>Liber '+roman(book)+'</h2><div class="loci">'+''.join('<a href="lectura/recensio-es/libro-'+roman(book).lower()+'.html#'+p['locus']+'">'+reference(p)+'</a>' for p in passages if p['book']==book)+'</div></div>')
 s=s[:start]+'\n'.join(blocks)+'\n'+s[end:];s=re.sub(r'<p>Click en locus.*?</p>','<p>731 referencias canónicas de los diez libros. Cada locus abre su texto latino y traducción castellana; la lectura funciona sin JavaScript. Versión '+VERSION+'.</p>',s);s=s.replace('<meta charset="utf-8">','<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">');s=s.replace("let txt=lib.textContent.toLowerCase();\nlib.style.display=txt.includes(q)?'block':'none';", "let visible=0;lib.querySelectorAll('.loci a').forEach(a=>{a.hidden=!a.textContent.toLowerCase().includes(q);if(!a.hidden)visible++;});lib.style.display=visible?'block':'none';")
 source.write_text(s)
 index=ROOT/'index.html';s=index.read_text();s=re.sub(r'<p class="search-note">.*?</p>','<p class="search-note">Buscá en los DOCX completos V514, V554 y V297: texto del tratado, estudios, comentarios, tablas y notas. Elegí «Solo el tratado» para concordancias por locus o «IA semántica E5» para consultas por significado. Los recuentos exactos se mantienen separados de las afinidades conceptuales. <a href="catalogo.html">Cobertura por edición</a> · <a href="lectura/index.html">Lectura por libros sin JavaScript</a>.</p>',s)
 for e in cat['editions']:
  if e.get('fulltext_index'):
   s=s.replace('href="'+e['read_url']+'"','href="pdf.html?edition='+e['id']+'"')
 fallback='<noscript><section class="wrap"><h2>Catálogo y lectura sin JavaScript</h2><p><a href="catalogo.html">Consultar las '+str(len(records))+' fichas del catálogo</a> · <a href="lectura/index.html">Leer los diez libros en latín y traducción</a> · <a href="loci.html">Índice completo de 731 loci</a></p><ul>'+''.join('<li><a href="'+e['pdf']+'">'+esc(e['title'])+' · '+esc(e['version'])+' · PDF completo</a></li>' for e in cat['editions'] if e.get('fulltext_index'))+'</ul><p>Las búsquedas interactivas requieren JavaScript; los textos y PDF anteriores son accesibles directamente.</p></section></noscript>'
 s=re.sub(r'<noscript>.*?</noscript>',fallback,s,flags=re.S);s=s.replace('Cargando las fichas bibliográficas…','Catálogo disponible · <a href="catalogo.html">Consultar todas las fichas</a>')
 index.write_text(s)
 audit=ROOT/'auditoria.html';s=audit.read_text();s=s.replace('53 referencias: 8 fichas marcadas como contrastadas y 45 pendientes',f'{len(studies)} referencias: 8 fichas marcadas como contrastadas y {len(studies)-8} pendientes').replace('38 entradas selectivas; 2 con fuente lexicográfica identificada y verificación local',f'{len(lexicon)} entradas selectivas; {sum(bool(e.get("verified")) for e in lexicon)} con verificación local declarada').replace('Completar el cotejo de las 45 fichas pendientes',f'Completar el cotejo de las {len(studies)-8} fichas pendientes')
 marker='<!--LIVE-COVERAGE-->';section='<section aria-labelledby="actualizacion-corpus"><h2 id="actualizacion-corpus">Actualización reproducible del corpus · '+VERSION+'</h2><p>Se incorporan '+str(coverage['fulltext_units'])+' unidades completas de los DOCX, incluidos estudios, tablas y '+str(len(notes))+' notas. Los PDF originales están disponibles en el sitio y en un visor con búsqueda, resaltado y navegación por locus.</p><p>El modo exacto excluye aproximaciones. Los índices latino y griego proceden del texto; los rangos se aplican solo a unidades con referencia explícita. '+str(coverage['notes']['explicit_locus'])+' notas tienen locus explícito y '+str(coverage['notes']['requires_locus_review'])+' requieren revisión de asociación.</p><p>IA E5: '+('matriz publicada para el corpus completo; evaluación temática inicial documentada' if cat['semantic']['status']=='published' else 'generación en curso; la publicación se confirma únicamente cuando la matriz está disponible')+'. La afinidad conceptual no certifica variantes ni sustituye una concordancia literal.</p><p><a href="data/coverage.json">Cobertura y estados calculados desde los archivos</a> · <a href="data/semantic-quality-report.json">Evaluación temática E5</a> · <a href="data/releases/'+VERSION+'.json">Manifiesto de versión</a> · <a href="catalogo.html">Catálogo accesible sin JavaScript</a></p><p>Los apartados históricos que figuran a continuación conservan las observaciones de la revisión inicial; esta actualización y los manifiestos enlazados prevalecen para cantidades y funciones publicadas. La revisión con lectores de pantalla y el cotejo filológico independiente siguen pendientes.</p></section>'
 if marker in s:s=re.sub(r'<!--LIVE-COVERAGE-->.*?<!--/LIVE-COVERAGE-->',marker+section+'<!--/LIVE-COVERAGE-->',s,flags=re.S)
 else:s=s.replace('<section id="balance-2026-10-30"',marker+section+'<!--/LIVE-COVERAGE--><section id="balance-2026-10-30"')
