 release={'version':VERSION,'date':'2026-10-30','title':'Vitruvius Digital Library · corpus completo y búsqueda verificable','sources':full['editions'],'files':{},'identifiers':{'doi':None,'orcid':None,'version_manifest':BASE+'data/releases/'+VERSION+'.json'},'notes':'No se asignan DOI, ORCID ni ISBN inexistentes. Los hashes identifican los archivos publicados.'}
