 pages=[p.relative_to(ROOT).as_posix() for p in ROOT.rglob('*.html') if '.git' not in p.parts];(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+esc(p)+'</loc></url>' for p in sorted(pages))+'</urlset>');(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'sitemap.xml\n')
